WITH lines AS (SELECT id, status_code, attr_key, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS attr_key, v) SELECT attr_key, CASE WHEN status_code >= 411 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_tier, AVG(status_code) AS avg_status_code, SORT_ARRAY(COLLECT_SET(attr_key)) AS attr_key_list FROM lines GROUP BY attr_key, CASE WHEN status_code >= 411 THEN 'PREMIUM' ELSE 'STANDARD' END;
